window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-87ffd887a9b11bbe"]={"versions": [{"id": "FIG-87ffd887a9b11bbe", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion zwischen dem generischen Netzwerk-Management (<code>Nm</code>) und dem LIN-spezifischen Netzwerk-Management (<code>LinNm</code>) innerhalb des AUTOSAR Communication Stacks. Es stellt synchrone Serviceaufrufe und zugehörige Zustandsübergänge des LIN-Netzwerk-Managements dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li><code>Nm</code>: Generische AUTOSAR-Netzwerk-Management-Schnittstelle als Aufrufer.\n</li><li><code>LinNm</code>: BSW-Modul für LIN-Netzwerk-Management als Ausführer.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>LinNm_NetworkRequest(nmChannelHandle) :Std_ReturnType</code>: Synchrone Schnittstelle zur Anforderung des Netzwerkbetriebs für den spezifizierten Kanal.\n</li><li><code>LinNm_NetworkRelease(nmChannelHandle) :Std_ReturnType</code>: Synchrone Schnittstelle zur Freigabe des Netzwerks für den spezifizierten Kanal.\n</li></ul>\n<p class=\"fig-p\">Zustands-Invariants auf der <code>LinNm</code>-Lebenslinie:</p>\n<ul class=\"fig-list\"><li><code>Network Mode</code>\n</li><li><code>Normal Operation</code>\n</li><li><code>Bus sleep mode</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Nm</code> initiiert über einen synchronen Aufruf <code>LinNm_NetworkRequest(nmChannelHandle)</code> die Netzwerkanforderung an <code>LinNm</code>, während sich <code>LinNm</code> im Zustand <code>Network Mode</code> befindet.\n</li><li><code>LinNm</code> verarbeitet den Aufruf und antwortet synchron an <code>Nm</code> mit <code>:Std_ReturnType</code>. <code>LinNm</code> verbleibt bzw. geht über in den Zustand <code>Normal Operation</code>.\n</li><li>Zu einem späteren Zeitpunkt ruft <code>Nm</code> synchron <code>LinNm_NetworkRelease(nmChannelHandle)</code> auf.\n</li><li><code>LinNm</code> verarbeitet die Freigabe und antwortet synchron an <code>Nm</code> mit <code>:Std_ReturnType</code>. Im Anschluss erfolgt der Übergang in den Zustand <code>Bus sleep mode</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Signatur der Funktionsaufrufe spezifiziert zwingend den Übergabeparameter <code>nmChannelHandle</code> sowie den Rückgabetyp <code>Std_ReturnType</code>. Entwickler müssen sicherstellen, dass Aufrufe von <code>LinNm_NetworkRequest</code> und <code>LinNm_NetworkRelease</code> blockierend bzw. synchron verarbeitet werden und der Rückgabewert (<code>E_OK</code>/<code>E_NOT_OK</code>) zur Quittierung der Zustandsübernahme ausgewertet wird. Die Zustandsfolgen bilden den normativen Pfad von aktivem Netzwerkbetrieb (<code>Network Mode</code> / <code>Normal Operation</code>) zurück in den Ruhezustand (<code>Bus sleep mode</code>) ab.</p>"}, {"id": "FIG-f4aed2c01077476a", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion zwischen dem generischen Netzwerk-Management (<code>Nm</code>) und dem LIN-spezifischen Netzwerk-Management (<code>LinNm</code>) innerhalb des AUTOSAR Communication Stacks. Es stellt synchrone Serviceaufrufe und zugehörige Zustandsübergänge des LIN-Netzwerk-Managements dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li><code>Nm</code>: Generische AUTOSAR-Netzwerk-Management-Schnittstelle als Aufrufer.\n</li><li><code>LinNm</code>: BSW-Modul für LIN-Netzwerk-Management als Ausführer.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>LinNm_NetworkRequest(nmChannelHandle)</code>: Synchrone Schnittstelle zur Anforderung des Netzwerkbetriebs für den spezifizierten Kanal.\n</li><li><code>LinNm_NetworkRelease(nmChannelHandle)</code>: Synchrone Schnittstelle zur Freigabe des Netzwerks für den spezifizierten Kanal.\n</li></ul>\n<p class=\"fig-p\">Zustands-Invariants auf der <code>LinNm</code>-Lebenslinie:</p>\n<ul class=\"fig-list\"><li><code>Network Mode</code>\n</li><li><code>Normal Operation</code>\n</li><li><code>Bus sleep mode</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Nm</code> initiiert über einen synchronen Aufruf <code>LinNm_NetworkRequest(nmChannelHandle)</code> die Netzwerkanforderung an <code>LinNm</code>, während sich <code>LinNm</code> im Zustand <code>Network Mode</code> befindet.\n</li><li><code>LinNm</code> verarbeitet den Aufruf und kehrt über eine synchrone Antwortnachricht zu <code>Nm</code> zurück. <code>LinNm</code> befindet sich im Zustand <code>Normal Operation</code>.\n</li><li>Zu einem späteren Zeitpunkt ruft <code>Nm</code> synchron <code>LinNm_NetworkRelease(nmChannelHandle)</code> auf.\n</li><li><code>LinNm</code> verarbeitet die Freigabe und kehrt synchron zu <code>Nm</code> zurück. Anschließend erfolgt der Übergang in den Zustand <code>Bus sleep mode</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Signatur der Funktionsaufrufe weist den Übergabeparameter <code>nmChannelHandle</code> auf; die Rückkehr erfolgt synchron über Reply-Nachrichten. Entwickler müssen sicherstellen, dass Aufrufe von <code>LinNm_NetworkRequest</code> und <code>LinNm_NetworkRelease</code> synchron abgewickelt werden. Die Zustandsinvariants definieren den verbindlichen Ablaufpfad für den LIN-Kanal von <code>Network Mode</code> über <code>Normal Operation</code> in den Zustand <code>Bus sleep mode</code>.</p>"}, {"id": "FIG-be4790b60a5da5b4", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion zwischen dem generischen Netzwerk-Management (<code>Nm</code>) und dem LIN-spezifischen Netzwerk-Management (<code>LinNm</code>) innerhalb des AUTOSAR Communication Stacks. Es stellt synchrone Serviceaufrufe und zugehörige Zustandsübergänge des LIN-Netzwerk-Managements dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (Stereotyp <code>«module»</code>):</p>\n<ul class=\"fig-list\"><li><code>Nm</code>: Generische AUTOSAR-Netzwerk-Management-Schnittstelle als Aufrufer.\n</li><li><code>LinNm</code>: BSW-Modul für LIN-Netzwerk-Management als Ausführer.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>LinNm_NetworkRequest(nmChannelHandle)</code>: Synchrone Schnittstelle zur Anforderung des Netzwerkbetriebs für den spezifizierten Kanal.\n</li><li><code>LinNm_NetworkRelease(nmChannelHandle)</code>: Synchrone Schnittstelle zur Freigabe des Netzwerks für den spezifizierten Kanal.\n</li></ul>\n<p class=\"fig-p\">Zustands-Invariants auf der <code>LinNm</code>-Lebenslinie:</p>\n<ul class=\"fig-list\"><li><code>Network Mode</code>\n</li><li><code>Normal Operation</code>\n</li><li><code>Bus sleep mode</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Nm</code> initiiert über einen synchronen Aufruf <code>LinNm_NetworkRequest(nmChannelHandle)</code> die Netzwerkanforderung an <code>LinNm</code>, während sich <code>LinNm</code> im Zustand <code>Network Mode</code> befindet.\n</li><li><code>LinNm</code> verarbeitet den Aufruf und kehrt über eine synchrone Antwortnachricht zu <code>Nm</code> zurück. <code>LinNm</code> befindet sich im Zustand <code>Normal Operation</code>.\n</li><li>Zu einem späteren Zeitpunkt ruft <code>Nm</code> synchron <code>LinNm_NetworkRelease(nmChannelHandle)</code> auf.\n</li><li><code>LinNm</code> verarbeitet die Freigabe und kehrt synchron zu <code>Nm</code> zurück. Anschließend erfolgt der Übergang in den Zustand <code>Bus sleep mode</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Signatur der Funktionsaufrufe weist den Übergabeparameter <code>nmChannelHandle</code> auf; die Rückkehr erfolgt synchron über Reply-Nachrichten. Entwickler müssen sicherstellen, dass Aufrufe von <code>LinNm_NetworkRequest</code> und <code>LinNm_NetworkRelease</code> synchron abgewickelt werden. Die Zustandsinvariants definieren den verbindlichen Ablaufpfad für den LIN-Kanal von <code>Network Mode</code> über <code>Normal Operation</code> in den Zustand <code>Bus sleep mode</code>.</p>"}], "trans": [{"from": "FIG-87ffd887a9b11bbe", "to": "FIG-f4aed2c01077476a", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Funktionsaufrufe <code>LinNm_NetworkRequest</code> und <code>LinNm_NetworkRelease</code>: Rückgabetyp <code>:Std_ReturnType</code> aus der Signatur entfernt (Angabe des Rückgabetyps entfällt in der Sequenzbeschriftung).\n</li></ul>"}, {"from": "FIG-f4aed2c01077476a", "to": "FIG-be4790b60a5da5b4", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
